// Run in an isolated agent-browser session: agent-browser eval --stdin < this-file
(async()=>{
const paths=['/collaboration','/work?view=calendar','/p/launch/work-items?view=calendar','/p/film/flow','/chat?channel_id=external','/overview','/work','/work?view=board','/projects','/p/launch','/p/film','/p/launch/work-items','/p/launch/work-items/W-104','/p/launch/work-items/W-104?tab=review','/p/launch/work-items/W-104?tab=plan','/p/launch/flow','/p/launch/flow?view=list','/p/launch/artifacts/W-103','/p/launch/artifacts/W-104','/p/film/artifacts/W-201','/p/novel/artifacts/W-301','/chat?channel_id=launch','/chat?channel_id=private','/chat?execution_id=EX-demo-W-104','/members','/agents','/agents/atlas','/machines','/machines/n1','/machines/n1?tab=files','/machines/n1?tab=terminal','/machines/n1?tab=preview','/goals','/goals/G-01','/reports','/reports/RP-01','/worklogs','/tests','/testplans','/defects','/repositories','/schedules','/health','/health/INC-01','/knowledge','/knowledge/K-02','/tools','/templates','/connectors','/connectors/CN-01','/models','/models/MD-02','/policies','/approvals','/invitations','/deliveries','/cost','/governance/audit','/settings','/work?state=empty','/work?state=loading','/work?state=error','/work?state=denied'];
const errors=[];window.addEventListener('error',e=>errors.push(e.message));window.addEventListener('unhandledrejection',e=>errors.push(String(e.reason)));
const result=[];for(const path of paths){location.hash=path;await new Promise(r=>setTimeout(r,130));result.push({path,heading:document.querySelector('main h1,main h2')?.textContent||document.querySelector('[role=status]')?.textContent,overflow:document.documentElement.scrollWidth>innerWidth+1,broken:!!document.querySelector('vite-error-overlay')||document.body.innerText.includes('页面暂时无法显示')});}
return JSON.stringify({viewport:innerWidth,pages:result,errors});
})()
